INSERT INTO QuizQuestion VALUES('c1febe74-8998-4827-8ca6-7237f774def7','Was ist die kleinste Informationseinheit in der Informatik?','Bit','["Bit","Byte","Kilobyte","Wort"]','p: Denke an die elementarste Form von Information in der Digitaltechnik.','Das Bit ist die kleinste Informationseinheit und kann nur die Werte 0 oder 1 annehmen.',1,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('2dec74b3-ee22-48a9-9ef8-8dac1353ca05','Wie viele Bits enthält ein Byte?','8','["8","4","16","10"]','p: Erinnere dich an die Standarddefinition von Byte in der Informatik.','Ein Byte besteht aus 8 Bits. Das ist ein weltweit etablierter Standard.',2,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('4ff6cca5-b184-4d5a-a357-33e5cd8309e0','Welche Zahl entspricht dem Binärwert 1010 im Dezimalsystem?','10','["10","8","12","15"]','p: Rechne jede Binärstelle in eine Zweierpotenz um und addiere sie.','1010₂ = 1·2³ + 0·2² + 1·2¹ + 0·2⁰ = 8 + 0 + 2 + 0 = 10.',3,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('b58ad9a9-f1b6-4c98-8374-bdbf7dbd87c6','Was bezeichnet die CPU in einem Computersystem?','Zentrale Verarbeitungseinheit','["Zentrale Verarbeitungseinheit","Speicherbaustein","Grafikkarte","Netzteil"]','p: Sie wird auch als Prozessor bezeichnet.','Die CPU (Central Processing Unit) ist das „Gehirn“ des Computers und führt Befehle aus.',4,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('2c98bfbd-6ab4-4ce1-9ff5-dbc2fd2ef65e','Welche Funktion hat das ALU in der CPU?','Führt arithmetische und logische Operationen aus','["Führt arithmetische und logische Operationen aus","Speichert temporäre Daten","Steuert den Datenfluss zwischen Ein- und Ausgabegeräten","Wandelt analoge Signale in digitale um"]','p: ALU steht für Arithmetic Logic Unit.','Die ALU führt mathematische (Addieren, Subtrahieren) und logische (UND, ODER, NICHT) Operationen aus.',5,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('bf9fdf86-5ce3-4aac-9068-af8a1b568863','Welches Zahlensystem wird in digitalen Schaltungen verwendet?','Binärsystem','["Binärsystem","Dezimalsystem","Hexadezimalsystem","Oktalsystem"]','p: Digitale Schaltungen arbeiten nur mit zwei Zuständen.','Im Binärsystem gibt es nur 0 und 1 – passend zu den zwei elektrischen Zuständen an/aus.',6,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('caf89a74-c15b-4ed9-8f94-df1fa5d69978','Welcher Speicher verliert seinen Inhalt nach dem Ausschalten?','RAM','["RAM","ROM","Flash-Speicher","Festplatte"]','p: Überlege, welcher Speicher nur mit Strom funktioniert.','RAM (Random Access Memory) ist flüchtig und verliert seinen Inhalt ohne Stromversorgung.',7,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('e9080466-269d-486a-9f5e-02c2e852817f','Welches Logikgatter liefert nur dann 0, wenn beide Eingänge 1 sind?','NAND','["NAND","UND","ODER","XOR"]','p: Es ist die Negation des UND-Gatters.','Ein NAND-Gatter liefert nur dann 0, wenn beide Eingänge 1 sind, sonst 1.',8,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('cb04a001-ea6f-4d73-a673-7eaeb273e3f8','Welche Wahrheitstafel gehört zum ODER-Gatter?','0/0 → 0, alle anderen Kombinationen → 1','["0/0 → 0, alle anderen Kombinationen → 1","Nur 1/1 → 1, sonst 0","Nur unterschiedliche Eingänge → 1","Immer 0, wenn mindestens ein Eingang 0 ist"]','p: OR bedeutet, dass mindestens einer der Eingänge 1 sein muss.','Beim ODER-Gatter ist der Ausgang nur 0, wenn beide Eingänge 0 sind.',9,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('a1bcd81e-aea7-4b27-861c-9e452a31f913','Was ergibt die ODER-Verknüpfung von 0 und 1?','1','["1","0","-1","2"]','p: Überlege, ob mindestens einer der Eingänge 1 ist.','0 ODER 1 ergibt 1, weil mindestens ein Eingang wahr ist.',10,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('2a4b8e85-098c-4671-bb67-8a53068c1271','Welches Bauteil ist für die Spannungsversorgung eines Computers verantwortlich?','Netzteil','["Netzteil","Mainboard","Prozessor","Arbeitsspeicher"]','p: Es wandelt die Netzspannung in die für den Computer benötigten Spannungen um.','Das Netzteil versorgt alle Komponenten mit der nötigen Spannung.',11,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('4b30d564-bcd7-406d-a6e9-24ae60f9931b','Wie nennt man den Zwischenspeicher zwischen CPU und RAM?','Cache','["Cache","Register","SSD","Bus"]','p: Er ist kleiner, aber schneller als der RAM.','Cache-Speicher speichert oft benötigte Daten, um Zugriffe zu beschleunigen.',12,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('02eeee15-515d-474e-92fc-ec97e189b19b','Wofür wird ein Multiplexer verwendet?','Auswahl eines von mehreren Eingangssignalen','["Auswahl eines von mehreren Eingangssignalen","Vervielfachung eines Signals","Verstärkung eines Signals","Fehlerkorrektur"]','Erklärung: Ein Multiplexer leitet das Signal eines von mehreren Eingängen an den Ausgang weiter.','',13,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('5c1c152b-a2ec-4ae9-9ae1-8232c31d1133','Welche Zahl ist im Hexadezimalsystem gleichbedeutend mit der Dezimalzahl 15?','F','["F","E","D","1F"]','p: Hexadezimalzahlen nutzen Ziffern 0–9 und Buchstaben A–F.','Im Hexadezimalsystem steht F für den Wert 15.',14,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('41895d07-91ef-480a-b1a0-ad60f64e5f8e','Was ist der Hauptvorteil von SSDs gegenüber HDDs?','Schnellere Zugriffszeiten','["Schnellere Zugriffszeiten","Höhere Speicherkapazität","Geringerer Preis pro GB","Mechanische Bauteile"]','p: Denke an die Geschwindigkeit beim Starten und Laden.','SSDs sind viel schneller, da sie keine beweglichen Teile haben.',15,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('80d29e2a-88e9-43ba-800a-3f5fdd2033b1','Was macht ein Decoder in der Digitaltechnik?','Wandelt binäre Eingaben in eindeutige Ausgänge um','["Wandelt binäre Eingaben in eindeutige Ausgänge um","Verstärkt das Eingangssignal","Speichert Daten dauerhaft","Mischt mehrere Signale"]','p: Er „übersetzt“ Binärcodes.','Ein Decoder wandelt binäre Codes in genau definierte Ausgänge um.',16,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('e4b4676e-c074-496f-8f54-e77570966fce','Welche Wahrheitstafel beschreibt das UND-Gatter?','Nur bei 1 und 1 ist der Ausgang 1','["Nur bei 1 und 1 ist der Ausgang 1","Nur bei 0 und 0 ist der Ausgang 1","Immer 1, wenn mindestens ein Eingang 1 ist","Immer 0, wenn beide Eingänge gleich sind"]','p: Es funktioniert wie die Schnittmenge zweier Bedingungen.','Das UND-Gatter liefert nur 1, wenn beide Eingänge 1 sind.',17,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('f9b543a8-a21e-4f25-b090-cd1cd2f4de49','Welche Wahrheitstafel gehört zum XOR-Gatter?','Ausgang = 1 nur bei ungleichen Eingängen','["Ausgang = 1 nur bei ungleichen Eingängen","Ausgang = 1 nur bei beiden Eingängen 1","Ausgang = 0 bei ungleichen Eingängen","Ausgang = 0 nur bei beiden Eingängen 0"]','p: XOR steht für „exklusives ODER“.','Das XOR-Gatter liefert 1, wenn genau einer der Eingänge 1 ist.',18,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('f2ff150b-8548-4cd0-b76d-b9eec04c6b18','Was ist ein Bus im Computersystem?','Ein System zur Datenübertragung zwischen Komponenten','["Ein System zur Datenübertragung zwischen Komponenten","Ein Speicherbereich im Prozessor","Ein Steuerbefehl im Assembler","Ein Stromversorgungskabel"]','p: Er verbindet die verschiedenen Komponenten des Systems.','Ein Bus überträgt Daten, Adressen oder Steuerinformationen zwischen Bauteilen.',19,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
INSERT INTO QuizQuestion VALUES('acece6d3-8f22-40ee-8473-fa86c727f794','Welche Logikfunktion entspricht der Negation von A ODER B?','NOR','["NOR","NAND","XOR","XNOR"]','p: Es ist das ODER mit nachgeschaltetem NICHT.','Das NOR-Gatter liefert nur 1, wenn beide Eingänge 0 sind.',20,'38793607-297f-49ff-948b-1ca68632a55c',1754890134836,1754890134836);
